def _np2(n):
    if n <= 1:
        return 1
    return 1 << (n - 1).bit_length()


def _can_cast(src, dst):
    fn = getattr(torch, "can_cast", None)
    if fn is not None:
        try:
            return bool(fn(src, dst))
        except Exception:
            pass
    if src == dst:
        return True
    if src.is_complex and not dst.is_complex:
        return False
    if src.is_complex and dst.is_complex:
        return src.itemsize <= dst.itemsize
    if src.is_floating_point and (dst.is_complex or not dst.is_floating_point):
        return False
    if not src.is_floating_point and dst.is_floating_point:
        return True
    return src.itemsize <= dst.itemsize


